package bo.edu.uagrm.saludu.agenda.api;
import bo.edu.uagrm.saludu.agenda.application.AvailabilityException;
import bo.edu.uagrm.saludu.identity.infrastructure.SessionPrincipal; import bo.edu.uagrm.saludu.shared.persistence.*; import bo.edu.uagrm.saludu.governance.application.AuditWriter; import bo.edu.uagrm.saludu.governance.domain.AuditOutcome; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/appointment-requests") public class AppointmentRequestController {private final JdbcTemplate j;private final DatabaseActorContext c;private final AuditWriter a;public AppointmentRequestController(JdbcTemplate j,DatabaseActorContext c,AuditWriter a){this.j=j;this.c=c;this.a=a;}private void x(SessionPrincipal p){c.apply(new DatabaseActor(p.id(),Set.copyOf(p.roles())));}@GetMapping @PreAuthorize("hasAnyRole('STUDENT','ADMINISTRATIVE')") @Transactional(readOnly=true) public LegacyAvailabilityResponse<List<Map<String,Object>>> list(@AuthenticationPrincipal SessionPrincipal p){x(p);return LegacyAvailabilityResponse.success(j.query("select * from salud_u.listar_mis_solicitudes_cita()",(r,n)->{Map<String,Object> item=new LinkedHashMap<>();item.put("id",r.getObject("id",UUID.class));item.put("appointment_type",r.getString("tipo_cita"));item.put("status",r.getString("estado"));item.put("requested_at",r.getObject("solicitado_en"));item.put("patient",Map.of("id",r.getObject("id_paciente",UUID.class),"carnet",r.getString("carnet"),"given_names",r.getString("nombre_paciente"),"family_names",""));item.put("appointment",null);return item;}));}@PostMapping @PreAuthorize("hasAnyRole('STUDENT','ADMINISTRATIVE')") @Transactional public org.springframework.http.ResponseEntity<?> create(@RequestBody Map<String,Object>b,@AuthenticationPrincipal SessionPrincipal p){String type=String.valueOf(b.getOrDefault("appointmentType","INITIAL"));x(p);if("REFERRAL".equals(type)){if(!p.roles().contains("ADMINISTRATIVE"))throw new AvailabilityException(403,"Sólo administración puede programar una derivación.");Object raw=b.get("referralId");if(!(raw instanceof String referralId)||referralId.isBlank())throw new AvailabilityException(400,"Selecciona una derivación.");UUID saved=j.queryForObject("select salud_u.crear_solicitud_derivacion(?)",UUID.class,UUID.fromString(referralId));a.append("REFERRAL_SCHEDULE_REQUEST_CREATED","appointment_request",saved,AuditOutcome.SUCCESS,Map.of("referralId",referralId));return org.springframework.http.ResponseEntity.status(201).body(LegacyAvailabilityResponse.success(Map.of("id",saved)));}if(!"INITIAL".equals(type))throw new AvailabilityException(400,"Tipo de solicitud no válido.");UUID id=null;if(b.get("patientId") instanceof String s&&!s.isBlank())id=UUID.fromString(s);if(p.roles().contains("STUDENT")&&id!=null)throw new AvailabilityException(403,"Una estudiante sólo puede solicitar su propia atención.");if(p.roles().contains("ADMINISTRATIVE")&&id==null)throw new AvailabilityException(400,"Selecciona un estudiante para crear la solicitud.");UUID saved=j.queryForObject("select salud_u.crear_solicitud_inicial(?)",UUID.class,id);a.append("APPOINTMENT_REQUEST_CREATED","appointment_request",saved,AuditOutcome.SUCCESS,Map.of());return org.springframework.http.ResponseEntity.status(201).body(LegacyAvailabilityResponse.success(Map.of("id",saved)));}@PatchMapping("/{id}") @PreAuthorize("hasAnyRole('STUDENT','ADMINISTRATIVE')") @Transactional public LegacyAvailabilityResponse<Void> cancel(@PathVariable UUID id,@RequestBody Map<String,Object>b,@AuthenticationPrincipal SessionPrincipal p){if(!"cancel".equals(b.get("action")))throw new AvailabilityException(400,"Acción no válida.");x(p);j.query("select salud_u.cancelar_solicitud_cita(?,?)",r->{},id,b.get("reason"));a.append("APPOINTMENT_REQUEST_CANCELLED","appointment_request",id,AuditOutcome.SUCCESS,Map.of());return LegacyAvailabilityResponse.success(null);}}
